//! 🧭️ Neutral full-dialect source qualification refuses stale reads before any child command is built.
use super::*;
static OWNER:ChildEditorCapability=ChildEditorCapability{artifact_kind:"s.draw.drawing",standard:"1",subset:"*",editor_id:"s.draw.drawing@1/*#editor",command_id:"editPath"};
static OTHER:ChildEditorCapability=ChildEditorCapability{artifact_kind:"s.draw.drawing",standard:"1",subset:"*",editor_id:"s.draw.drawing@1/*#editor",command_id:"editPath"};
fn revision(value:&serde_json::Value,key:&str)->[u8;32]{let text=value[key].as_str().unwrap();std::array::from_fn(|at|u8::from_str_radix(&text[at*2..at*2+2],16).unwrap())}
fn fields<'a>(value:&'a serde_json::Value,parent:&'a[u8;32],child:&'a[u8;32])->ChildEditorFields<'a>{ChildEditorFields{parent_artifact:value["parentArtifact"].as_str().unwrap(),owner:value["owner"].as_str().unwrap(),slot:value["slot"].as_str().unwrap(),child_id:value["childId"].as_str().unwrap(),artifact_id:value["artifactId"].as_str().unwrap(),artifact_kind:value["artifactKind"].as_str().unwrap(),standard:value["standard"].as_str().unwrap(),subset:value["subset"].as_str().unwrap(),editor_id:value["editorId"].as_str().unwrap(),command_id:value["commandId"].as_str().unwrap(),parent_revision:parent,child_revision:child}}
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1}}
#[test]fn neutral_child_editor_source_matches_exact_canonical_owner_and_revisions(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){let rp=revision(&row["request"],"parentRevision");let rc=revision(&row["request"],"childRevision");let cp=revision(&row["current"],"parentRevision");let cc=revision(&row["current"],"childRevision");let request=ChildEditorRequest{identity:11,expected_reference_identity:44,fields:fields(&row["request"],&rp,&rc)};let current=ChildEditorCurrent{parent_identity:22,child_identity:33,fields:fields(&row["current"],&cp,&cc),capability:&OWNER};let mut cursor=ChildEditorSourceCursor::new();let mut terminal=false;for _ in 0..10000{let demand=cursor.next_demand();for denied in [RetainedCloneGrant{maximum_items:0,..grant()},RetainedCloneGrant{maximum_depth:0,..grant()},RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes-1,..grant()}]{let before=cursor.progress();assert!(matches!(cursor.advance(&request,&current,denied).unwrap(),ChildEditorSourceStep::Pending));assert_eq!(cursor.progress(),before);assert_eq!(cursor.last_receipt(),Default::default());}match cursor.advance(&request,&current,grant()){Ok(ChildEditorSourceStep::Pending)=>{},Ok(ChildEditorSourceStep::Ready(stamp))=>{assert!(row["accepted"].as_bool().unwrap());assert_eq!(stamp.command_identity(),11);assert_eq!(stamp.expected_reference_identity(),44);assert_eq!(stamp.parent_identity(),22);assert_eq!(stamp.child_identity(),33);assert_eq!(stamp.parent_revision(),&cp);assert_eq!(stamp.child_revision(),&cc);terminal=true;break;},Err(_)=>{assert!(!row["accepted"].as_bool().unwrap());terminal=true;break;}}assert!(cursor.last_receipt().fits(grant()));}assert!(terminal);cursor.cancel();assert!(cursor.advance(&request,&current,grant()).is_err());assert!(!cursor.close_one(RetainedCloneGrant{maximum_items:0,..grant()}));assert!(cursor.close_one(grant()));assert!(cursor.terminal_is_empty());}}
#[test]fn original_child_editor_source_identity_cannot_be_substituted_with_equal_values(){let revision=[1;32];let source=ChildEditorFields{parent_artifact:"layout",owner:"",slot:"backgroundDrawing",child_id:"drawing",artifact_id:"artifact",artifact_kind:OWNER.artifact_kind,standard:OWNER.standard,subset:OWNER.subset,editor_id:OWNER.editor_id,command_id:OWNER.command_id,parent_revision:&revision,child_revision:&revision};for changed in 0..5{let request=ChildEditorRequest{identity:11,expected_reference_identity:44,fields:source};let mut current=ChildEditorCurrent{parent_identity:22,child_identity:33,fields:source,capability:&OWNER};let mut cursor=ChildEditorSourceCursor::new();cursor.advance(&request,&current,grant()).unwrap();let next=ChildEditorRequest{identity:if changed==0{12}else{11},expected_reference_identity:if changed==4{45}else{44},fields:source};match changed{1=>current.parent_identity=23,2=>current.child_identity=34,3=>current.capability=&OTHER,_=>{}}assert!(cursor.advance(&next,&current,grant()).is_err());assert_eq!(cursor.last_receipt(),Default::default());cursor.cancel();assert!(cursor.close_one(grant()));}}
